// A tiny, real two-page PDF with selectable text.
function pdf(paddingBytes=0){const objects=['<< /Type /Catalog /Pages 2 0 R >>','<< /Type /Pages /Kids [3 0 R 5 0 R] /Count 2 >>','<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 7 0 R >> >> /Contents 4 0 R >>',null,'<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 7 0 R >> >> /Contents 6 0 R >>',null,'<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>'];const stream=(title,body)=>{const data=`BT /F1 22 Tf 62 705 Td (${title}) Tj 0 -42 Td /F1 12 Tf (${body}) Tj 0 -24 Td (Select this sentence to discuss it with your writing agent.) Tj ET`;return `<< /Length ${Buffer.byteLength(data)} >>\nstream\n${data}\nendstream`;};objects[3]=stream('Evidence begins with a clear question','Training and validation curves should share a common axis.');objects[5]=stream('Limitations guide the next experiment','Negative results explain which assumptions need to change.');if(paddingBytes)objects.push(`<< /Length ${paddingBytes} >>\nstream\n${' '.repeat(paddingBytes)}\nendstream`);let body='%PDF-1.4\n',offsets=[0];objects.forEach((obj,index)=>{offsets.push(Buffer.byteLength(body));body+=`${index+1} 0 obj\n${obj}\nendobj\n`;});const start=Buffer.byteLength(body);body+=`xref\n0 ${objects.length+1}\n0000000000 65535 f \n`+offsets.slice(1).map(value=>String(value).padStart(10,'0')+' 00000 n \n').join('')+`trailer\n<< /Size ${objects.length+1} /Root 1 0 R >>\nstartxref\n${start}\n%%EOF`;return Buffer.from(body);}
module.exports=pdf;
